  "msg.bad.mine_exhausted": { en: "The ore has run out: the mines of that kind have stopped. Their pits still need restoring", th: "แร่หมดแล้ว เหมืองแร่ชนิดนั้นหยุดทำงาน หลุมเหมืองยังต้องฟื้นฟู" },
  "msg.bad.oil_spill": { en: "Oil spill! A well has poisoned the ground around it", th: "น้ำมันรั่ว! บ่อน้ำมันทำให้ดินรอบ ๆ ปนเปื้อน" },
  "msg.bad.toxic_ground": { en: "The mines are poisoning the ground and the groundwater around them", th: "สารพิษจากเหมืองปนเปื้อนดินและน้ำใต้ดินรอบ ๆ" },
  "msg.bad.haze": { en: "Haze! Stubble fires on the farms are filling the air with smoke", th: "หมอกควัน! การเผาไร่ทำให้อากาศเต็มไปด้วยควัน" },
  "msg.bad.few_fish": { en: "The fish are running low: fewer harbours would let them grow back", th: "ปลาเริ่มหมด ลดจำนวนท่าเรือประมงเพื่อให้ปลาฟื้นตัว" },
  "msg.bad.dirty_harbour": { en: "Dirty water at a fishing harbour is halving the catch", th: "น้ำเสียแถวท่าเรือประมงทำให้จับปลาได้ลดลงครึ่งหนึ่ง" },
  "msg.bad.ruler_house_lost": { en: "The ruler's house is gone: the city loses its centre and the house's wings until it is built again", th: "จวนเจ้าเมืองพังแล้ว เมืองเสียใจกลางเมืองและส่วนต่อเติมจนกว่าจะสร้างใหม่" },
  "msg.bad.fire_season_ahead": { en: "Warning tower: the wildfire season begins next month", th: "หอเตือนภัย: เดือนหน้าเข้าฤดูไฟป่า" },
  "msg.bad.flood_season_ahead": { en: "Warning tower: the flood season begins next month", th: "หอเตือนภัย: เดือนหน้าเข้าฤดูน้ำท่วม" },
  "msg.bad.storm_season_ahead": { en: "Warning tower: the storm season begins next month", th: "หอเตือนภัย: เดือนหน้าเข้าฤดูพายุ" },
  "msg.bad.few_schools": { en: "Too few schools: families are leaving for towns with places for their children", th: "เด็ก ๆ มีที่เรียนไม่พอ ครอบครัวเริ่มย้ายไปเมืองที่มีโรงเรียน" },
  "msg.bad.few_hospitals": { en: "Too few hospitals: people worry about falling ill here", th: "โรงพยาบาลไม่พอ คนเริ่มกังวลเรื่องเจ็บป่วย" },
  "msg.bad.rubbish_overflow": { en: "Rubbish is piling up in the streets: build a landfill or an incinerator", th: "ขยะล้นเมือง กองอยู่ตามถนน ควรสร้างบ่อฝังกลบหรือโรงเผาขยะ" },
  "msg.bad.landfill_full": { en: "A landfill is full and takes no more rubbish", th: "บ่อฝังกลบขยะเต็มแล้ว รับขยะเพิ่มไม่ได้" },
  "msg.bad.untreated_sewage": { en: "The town's sewage runs untreated into the water: fishing and visitors suffer", th: "น้ำเสียของเมืองไหลลงแหล่งน้ำโดยไม่ผ่านการบำบัด ประมงและการท่องเที่ยวเสียหาย" },
  "msg.bad.ship_crash": { en: "Shipwreck reported in waters!", th: "รายงานอุบัติเหตุเรือชนกันหรือเรืออับปาง!" },
  "msg.bad.high_crime": { en: "Crime rate is dangerously high!", th: "สถิติอาชญากรรมพุ่งสูงขึ้นขั้นวิกฤต!" },
  "msg.bad.high_pollution": { en: "Air & water pollution dangerously high!", th: "มลพิษทางอากาศและสิ่งแวดล้อมเกินค่ามาตรฐาน!" },
  "msg.bad.monster": { en: "A Giant Naga has emerged !", th: "พญานาคยักษ์ปรากฏกายขึ้นแล้ว !" },
  "msg.bad.tornado": { en: "Severe tornado spotted!", th: "พายุงวงช้างพัดถล่มบ้านเรือนเสียหาย!" },
  "msg.bad.meltdown": { en: "Nuclear reactor meltdown occurred !!", th: "เตาปฏิกรณ์นิวเคลียร์หลอมละลาย เกิดการรั่วไหล !!" },
  "msg.bad.tax_too_high": { en: "Citizens upset: local taxes are too high!", th: "ประชาชนไม่พอใจอย่างยิ่ง: อัตราภาษีท้องถิ่นแพงเกินไป!" },
  "msg.bad.no_money": { en: "YOUR CITY HAS GONE BANKRUPT!", th: "คลังเมืองล้มละลายแล้ว! เงินหมดเกลี้ยง!" },
  "msg.good.reach_town": { en: "Population reached 2,000 (Town level)", th: "ประชากรในเมืองทะลุ 2,000 คนแล้ว (ยกฐานะเป็นตำบล)" },
  "msg.good.tourist_season": { en: "The high season has begun: more visitors are coming", th: "เข้าฤดูท่องเที่ยวแล้ว นักท่องเที่ยวมามากขึ้น" },
  "msg.good.songkran": { en: "Songkran: people come home and visitors fill the city; the water fights use up water", th: "สงกรานต์ คนกลับบ้านและนักท่องเที่ยวมาเต็มเมือง เล่นน้ำกันจนน้ำประปาหายไปส่วนหนึ่ง" },
  "msg.good.new_year": { en: "New Year holidays: people come home and travel all over the country", th: "ช่วงปีใหม่ คนกลับบ้านและเที่ยวกันทั่วประเทศ" },
  "msg.good.reach_city": { en: "Population reached 10,000 (City level)", th: "ประชากรในเมืองทะลุ 10,000 คนแล้ว (ยกฐานะเป็นอำเภอ)" },
  "msg.good.reach_capital": { en: "Population reached 50,000 (Province level)", th: "ประชากรในเมืองทะลุ 50,000 คนแล้ว (ยกฐานะเป็นจังหวัด)" },
  "msg.good.reach_metro": { en: "Population reached 100,000 (Metropolis level)", th: "ประชากรในเมืองทะลุ 100,000 คนแล้ว (ยกฐานะเป็นนคร)" },
  "msg.good.reach_megalopolis": { en: "Population reached 500,000 (Megalopolis level)", th: "ประชากรในเมืองทะลุ 500,000 คนแล้ว (ยกฐานะเป็นมหานคร)" },
