  "monstertv.btn.close": { en: "Close TV", th: "ปิดกล้องวงจรปิด" },
  "debug.fps": { en: "{val} FPS", th: "{val} FPS" },
  "debug.btn.debug": { en: "Debug", th: "ดีบัก" },
  "debug.window.title": { en: "Debug Tools", th: "เครื่องมือทดสอบ (ดีบัก)" },
  "debug.window.funds": { en: "Grant ฿20,000 funds:", th: "เพิ่มเงินคลัง ฿20,000:" },
