  "sound.waiting": { en: "Click anywhere, or here, to start the sound (browsers keep games silent until then)", th: "คลิกที่ไหนก็ได้หรือที่ปุ่มนี้เพื่อเริ่มเสียง (เบราว์เซอร์ไม่ให้เกมมีเสียงจนกว่าจะคลิก)" },
  "sound.waiting_short": { en: "Sound on", th: "เปิดเสียง" },
  "footer.map_credit": { en: "Province maps: map data © {osm} (ODbL) · province shapes from {ne}.", th: "แผนที่จังหวัด: ข้อมูลแผนที่ © {osm} (ODbL) · รูปร่างจังหวัดจาก {ne}" },
  "splash.tagline": { en: "Choose a province of Thailand and build it up as its ruler.", th: "เลือกจังหวัดในประเทศไทย แล้วสร้างบ้านแปงเมืองในฐานะเจ้าเมือง" },
  "splash.btn.province": { en: "Choose your province", th: "เลือกจังหวัดที่จะเป็นเจ้าเมือง" },
  "splash.btn.continue": { en: "Continue: {city}", th: "เล่นต่อ: {city}" },
  "splash.practice": { en: "Or practise on a random map", th: "หรือฝึกเล่นบนแผนที่สุ่ม" },
  "splash.replay_intro": { en: "Watch the story again", th: "ดูเรื่องเล่าเปิดเกมอีกครั้ง" },
  "intro.title": { en: "The land awaits its builders", th: "แผ่นดินรอผู้สร้าง" },
  "intro.skip": { en: "Skip the story", th: "ข้ามเรื่องเล่า" },
  "intro.next": { en: "Next", th: "ถัดไป" },
  "intro.scroll": { en: "Scroll down", th: "เลื่อนลง" },
  "intro.thailand.title": { en: "Thailand", th: "ประเทศไทย" },
  "intro.thailand.text": { en: "The Golden Peninsula: a land at the heart of mainland Southeast Asia, with mountains in the north, a wide plateau, a great river plain and two seas.", th: "แหลมทอง ดินแดนใจกลางแผ่นดินใหญ่เอเชียตะวันออกเฉียงใต้ มีเทือกเขาทางเหนือ ที่ราบสูงกว้างใหญ่ ที่ราบลุ่มแม่น้ำ และทะเลสองฝั่ง" },
  "intro.regions.title": { en: "77 provinces, 6 regions", th: "77 จังหวัด 6 ภาค" },
  "intro.regions.text": { en: "Each region has its own landscape, homes and way of life.", th: "แต่ละภาคมีภูมิประเทศ บ้านเรือน และวิถีชีวิตเป็นของตัวเอง" },
  "intro.final.title": { en: "Become a city ruler", th: "มาเป็นเจ้าเมือง" },
  "intro.final.text": { en: "Every province is waiting for someone to build it up. Choose the region you want to live in, then your province.", th: "ทุกจังหวัดกำลังรอผู้สร้าง เลือกภาคที่คุณอยากไปอยู่ แล้วเลือกจังหวัดของคุณ" },
  "intro.final.button": { en: "Choose a region", th: "เลือกภาค" },
  "region.north.desc": { en: "High mountains, teak forests and cool winters.", th: "ภูเขาสูง ป่าสัก และหน้าหนาวที่อากาศเย็น" },
  "region.north.pros": { en: "Tourism and strong demand for shops", th: "การท่องเที่ยว และความต้องการร้านค้าสูง" },
  "region.north.cons": { en: "Thick forest to clear before building", th: "ป่าทึบ ต้องถางก่อนสร้าง" },
  "region.northeast.desc": { en: "A wide plateau of rice fields, bounded by the Mekong River.", th: "ที่ราบสูงกว้างใหญ่ ทุ่งนา และแม่น้ำโขง" },
  "region.northeast.pros": { en: "Cheap land and farm industry", th: "ที่ดินถูก และอุตสาหกรรมการเกษตร" },
  "region.northeast.cons": { en: "Droughts", th: "ภัยแล้ง" },
  "region.central.desc": { en: "The Chao Phraya river plain, the rice bowl of the country.", th: "ที่ราบลุ่มแม่น้ำเจ้าพระยา อู่ข้าวอู่น้ำของประเทศ" },
