  "goals.title.luang": { en: "Luang's tasks: a great city", th: "ภารกิจหลวง: หัวเมืองใหญ่" },
  "goals.airport": { en: "Build an airport", th: "สร้างสนามบิน" },
  "goals.airport.hint": { en: "Big shopping districts need an airport to keep growing. It is costly and noisy, so give it open land away from homes.", th: "ย่านการค้าใหญ่ต้องมีสนามบินจึงจะโตต่อได้ ราคาแพงและเสียงดัง วางบนที่โล่งให้ห่างบ้าน" },
  "goals.clean": { en: "Clean air", th: "อากาศสะอาด" },
